WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY quantity DESC, id) AS dedup_rank FROM order_items) x WHERE dedup_rank = 1), enriched AS (SELECT *, COUNT(quantity) OVER w_recent AS running_count_quantity, AVG(quantity) OVER w_recent AS running_avg_quantity, SUM(quantity) OVER w_recent AS running_sum_quantity, MAX(quantity) OVER w_recent AS running_max_quantity, LEAD(unit_price, 1) OVER (ORDER BY quantity, id) AS next_unit_price FROM latest WINDOW w_recent AS (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), latest_order_items AS (SELECT id, order_id, product_id, unit_price, dedup_rank, running_count_quantity, running_avg_quantity, running_max_quantity FROM enriched QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY running_max_quantity, id) = 1), matched_keys AS (SELECT id, product_id FROM latest_order_items INTERSECT SELECT id, product_id FROM order_items WHERE quantity < 3), verified AS (SELECT s.* FROM latest_order_items s JOIN matched_keys k ON s.id = k.id AND s.product_id = k.product_id), with_windows AS (SELECT *, MIN(running_count_quantity) OVER (PARTITION BY order_id) AS order_id_min_running_count_quantity, RANK() OVER (ORDER BY running_count_quantity DESC NULLS LAST) AS running_count_quantity_rank, MAX(running_count_quantity) OVER (PARTITION BY product_id) AS product_id_max_running_count_quantity, ROUND(running_count_quantity / SUM(running_count_quantity) OVER (PARTITION BY product_id), 4) AS running_count_quantity_share FROM verified), base AS (SELECT *, ROUND(product_id_max_running_count_quantity * 1.1, 2) AS product_id_max_running_count_quantity_adjusted FROM with_windows WHERE running_max_quantity BETWEEN 4.0 AND 7.7), with_dims AS (SELECT e.*, o.amount, o.status FROM base e JOIN orders o ON e.order_id = o.id WHERE o.status IN ('SHIPPED', 'COMPLETED', 'RETURNED')) SELECT p.brand, p.category, s.status, COUNT(*) AS cnt, SUM(s.unit_price) AS total_unit_price, MIN(s.running_count_quantity_rank) AS min_running_count_quantity_rank, GROUPING_ID() AS level_id FROM with_dims s JOIN products p ON s.product_id = p.id GROUP BY ROLLUP (p.brand, p.category, s.status);
